const planeacionId = $('Webhook').first().json.body.planeacion_id;
let raw = $('AIAgent').first().json.output ?? $('AIAgent').first().json.text ?? '';
if (typeof raw !== 'string') {
  return [{ json: { actividad: raw, planeacion_id: planeacionId } }];
}
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
const first = raw.indexOf('{');
const last = raw.lastIndexOf('}');
if (first !== -1 && last !== -1) {
  raw = raw.substring(first, last + 1);
}
const actividad = JSON.parse(raw);
return [{ json: { actividad, planeacion_id: planeacionId } }];
